  if(action==='train') { if(!state.trainProductId) return toast('Chọn món cần huấn luyện.',true); const readiness=await perform(()=>api(`/api/forecast/training-readiness?branchId=${state.branch}&productId=${state.trainProductId}`)); if(!readiness) return; state.data.trainingReadiness=readiness; forecast(); if(!readiness.ready) return toast(`Chưa đủ dữ liệu: ${readiness.consecutiveDays}/${readiness.requiredDays} ngày bán liên tiếp đã hoàn tất.`,true); if(!confirm('Huấn luyện mô hình từ đơn đã thanh toán của món này có thể mất vài phút. Tiếp tục?')) return; await perform(()=>api('/api/forecast/train',{method:'POST',body:{branchId:state.branch,productId:state.trainProductId,epochs:50}}),'Huấn luyện hoàn tất.'); return; }
